// Источник: web-тест .qa/e2e/tests/registration/rg-02-consent-keyboard-progress-aria.spec.ts, план .qa/e2e/specs/registration.md, кейс .qa/tests/registration/RG-02-consent-keyboard-progress-aria.md
// Тикеты #6a8edf78 #6a98690c. Нативный аналог: чекбокс согласия переключается касанием (в web — клавиша Space), «שלח» неактивна без согласия.
// aria-valuemin/max/now у progressbar — атрибуты web; на устройстве — ручная проверка (TalkBack/VoiceOver). Форма НЕ отправляется.
import { $, expect, driver } from '@wdio/globals';
import { byText, byLabel, tapLabel, tapText, scrollToText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, toHome } from '../../helpers/app.ts';
/** Минимальный тип элемента (подходит и для WebdriverIO.Element, и для ChainablePromiseElement). */
type El = {
  getAttribute(name: string): Promise<string | null>;
  isSelected(): Promise<boolean>;
  getLocation(): Promise<{ x: number; y: number }>;
  getSize(): Promise<{ width: number; height: number }>;
};

/** Выход: профиль → «התנתקות» (+ подтверждение, если есть) → splash. */
async function logout() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await (await scrollToText('התנתקות')).click();
  await driver.waitUntil(async () => {
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) return true;
    const confirm = await byText('התנתקות');
    if (await confirm.isDisplayed().catch(() => false)) await confirm.click().catch(() => {});
    return false;
  }, { timeout: 20000, interval: 700, timeoutMsg: 'после «התנתקות» не открылся splash' });
}
/** Вернуться к splash/входу и войти снова (login() начинает со splash или экрана номера). */
async function restoreLogin() {
  for (let i = 0; i < 4; i++) {
    if (await isLoggedIn()) return;
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) break;
    if (await byText('כניסה דרך מספר נייד').isDisplayed().catch(() => false)) break;
    await driver.back();
  }
  await ensureAppReady();
}

function button(text: string) {
  return driver.isAndroid ? $(`//*[@text="${text}"]/ancestor-or-self::*[@clickable="true"][1]`) : byText(text);
}
async function checked(el: El) {
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true';
  const v = await el.getAttribute('value');
  return v === '1' || v === 'true' || (await el.isSelected().catch(() => false));
}
async function tapJoin() {
  const t = await byText('הצטרפו אלינו');
  if (await t.isDisplayed().catch(() => false)) return t.click();
  return tapLabel('הצטרפו אלינו');
}

describe('Регистрация', () => {
  before(async () => { await logout(); });
  after(async () => { await restoreLogin(); });

  it('RG-02 Экран регистрации: чекбокс согласия переключается, «שלח» неактивна без согласия #6a8edf78 #6a98690c @prod-safe', async () => {
    // 1. Открыть регистрацию: splash → «בואו נתחיל» → «הצטרפו אלינו».
    await tapText('בואו נתחיל');
    await (await byText('כניסה דרך מספר נייד')).waitForDisplayed({ timeout: 20000 });
    await tapJoin();
    await (await byText('יצירת חשבון')).waitForDisplayed({ timeout: 20000 });
    await scrollToText('שלח');
    const consent = await byLabel('אני מאשר את תנאי השימוש ואת מדיניות הפרטיות');
    await expect(consent).toBeDisplayed();
    expect(await checked(consent)).toBe(false);
    await expect(button('שלח')).toBeDisabled();

    // 2–3. Касание → отмечен; ещё касание → снят; «שלח» снова неактивна.
    await consent.click();
    await driver.waitUntil(async () => checked(await byLabel('אני מאשר את תנאי השימוש ואת מדיניות הפרטיות')), { timeoutMsg: 'чекбокс не отметился' });
    await (await byLabel('אני מאשר את תנאי השימוש ואת מדיניות הפרטיות')).click();
    await driver.waitUntil(async () => !(await checked(await byLabel('אני מאשר את תנאי השימוש ואת מדיניות הפרטיות'))), { timeoutMsg: 'чекбокс не снялся' });
    await expect(button('שלח')).toBeDisabled();
  });
});
